import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.DSQXGnvq.js";const f=JSON.parse('{"title":"模拟器","description":"","frontmatter":{},"headers":[],"relativePath":"simulators.md","filePath":"simulators.md"}'),p={name:"simulators.md"};function i(o,e,s,c,l,h){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="模拟器" tabindex="-1">模拟器 <a class="header-anchor" href="#模拟器" aria-label="Permalink to &quot;模拟器&quot;">​</a></h1><p>本页介绍当前主要的开源电路模拟器。</p><p>你可以在 <a href="https://archive.fosdem.org/2017/schedule/track/electronic_design_automation_eda" target="_blank" rel="noreferrer">FOSDEM&#39;17 电子设计自动化专题</a> 中了解开源电路仿真的最新动态。</p><h2 id="ngspice" tabindex="-1">Ngspice <a class="header-anchor" href="#ngspice" aria-label="Permalink to &quot;Ngspice&quot;">​</a></h2><p><a href="http://ngspice.sourceforge.net" target="_blank" rel="noreferrer">Ngspice</a> 是一个混合级/混合信号电路仿真器，基于三个开源软件包：Spice3f5、Cider1b1 和 Xspice。</p><p><strong>Spice3f5</strong> 是 Berkeley 发布的 Spice3 系列模拟器的最后一个版本。</p><p><strong>Cider</strong> 将 Spice3f5 电路级模拟器与 DSIM 器件模拟器耦合，为关键器件提供更高的仿真精度。DSIM 器件通过结构和材料进行描述。</p><p><strong>Xspice</strong> 是 Ngspice 的扩展，提供代码建模支持和通过嵌入式事件驱动算法仿真数字组件。</p><p>Ngspice 的主要缺点是继承了 Berkeley SPICE 的旧 C 代码库。</p><p>更多信息见 <a href="http://ngspice.sourceforge.net/docs.html" target="_blank" rel="noreferrer">Ngspice 文档页面</a>。</p><h2 id="xyce" tabindex="-1">Xyce <a class="header-anchor" href="#xyce" aria-label="Permalink to &quot;Xyce&quot;">​</a></h2><p><a href="https://xyce.sandia.gov" target="_blank" rel="noreferrer">Xyce</a> 是一个开源、SPICE 兼容、高性能的模拟电路模拟器，能够求解极大规模的电路问题，由 <a href="http://www.sandia.gov" target="_blank" rel="noreferrer">Sandia 国家实验室</a> 开发。</p><p>Sandia 是美国参与国家核武器计划的实验室。其法国对应机构是 CEA（Alternative Energies and Atomic Energy Commission）。</p><p>Sandia 已发布多个开源程序。</p><p>Xyce 在 Sandia 从零开发，旨在满足特殊需求（如辐射下的芯片仿真）。Xyce 使用 C++ 开发。</p><h2 id="gnucap" tabindex="-1">Gnucap <a class="header-anchor" href="#gnucap" aria-label="Permalink to &quot;Gnucap&quot;">​</a></h2><p>Gnucap 最初由 Albert Davis 于 1983 年开发，2001 年作为 GNU 项目发布。</p><p>与 Xyce 一样，Gnucap 从零使用 C++ 开发。</p><p>2015 年，德国法兰克福大学发布了用于研究和实验的分支 <a href="http://www.em.informatik.uni-frankfurt.de/gnucap" target="_blank" rel="noreferrer">Gnucap-uf</a>。</p><p>Felix Salfelder 正在进行反向合并并添加新扩展。</p><h2 id="qucs" tabindex="-1">Qucs <a class="header-anchor" href="#qucs" aria-label="Permalink to &quot;Qucs&quot;">​</a></h2><p><a href="http://qucs.sourceforge.net" target="_blank" rel="noreferrer">QUCS</a>（通用电路仿真器）是 Michael Margraf、Stefan Jahn 等人开发的、具有类似 LTspice IDE 的电路仿真器。</p><p>QUCS 目前维护进展缓慢，Qt3 到 Qt4 的移植已持续多年。</p><p>可在 <a href="https://archive.fosdem.org/2017/schedule/event/qucs" target="_blank" rel="noreferrer">Guilherme Brondani Torri 的 FOSDEM&#39;17 演讲</a>中了解项目更新。</p>',24)])])}const u=a(p,[["render",i]]);export{f as __pageData,u as default};
